void can_per_init( UInt8 size   ) 
{
    Can_Per_Node *can_per_node ; 
    UInt8 i ; 
    
    can_per_fifo_free = fifo_create(); 	
	can_per_fifo_exec = fifo_create();
    
    for( i = 0 ; i < size ; i ++ )
    {
        can_per_node = can_per_node_free_create();
                
        fifo_insert( can_per_fifo_free , (Fifo_Node*) can_per_node );         
    }	
    
    per_exec_register( (Per_Exec_Func)can_per_execute );
}

